    $id = '<p><strong>[empresa campo="razao_social"]</strong><br>NIF [empresa campo="nif"]<br>[empresa campo="morada"], [empresa campo="cp_localidade"]<br>Registo comercial: [empresa campo="registo"]<br>E-mail: [empresa campo="email"] · Telefone: [empresa campo="telefone"]</p>';

    return [
        'sobre-nos' => ['Sobre nós', '<p>Esta loja online vende eletrodomésticos para o conforto da casa, com foco em desumidificadores e na qualidade do ar interior.</p><p>A informação sobre a empresa responsável pela loja está nesta página e nos Termos e Condições.</p>' . $id],
        'contactos' => ['Contactos', $id . '<p>Horário de atendimento: [empresa campo="horario"]</p><p>Para exercer o direito de livre resolução, use o <a href="/livre-resolucao/">formulário próprio</a>.</p>'],
        'perguntas-frequentes' => ['Perguntas frequentes', '<h2>Que capacidade de desumidificador preciso?</h2><p>Depende da área, do nível de humidade e da ventilação da divisão. A ficha de cada produto indica a capacidade e a área para que foi concebido.</p><h2>Compressor ou exsicante?</h2><p>Os modelos com compressor funcionam bem em ambientes temperados e húmidos. Os exsicantes mantêm o desempenho em divisões frias, como garagens e arrecadações.</p><h2>Como se cuida do aparelho?</h2><p>Esvazie o depósito e limpe o filtro com regularidade, seguindo o manual do fabricante.</p><h2>Que garantia têm os produtos?</h2><p>Os bens novos têm garantia legal de 3 anos. Ver <a href="/garantia/">Garantia</a>.</p><h2>Como posso pagar?</h2><p>Os meios de pagamento disponíveis são apresentados no checkout.</p>'],
        'entregas' => ['Entregas', '<p>Prazo de entrega: [a definir].<br>Custos de envio: [a definir].<br>Zonas servidas: [a definir].</p><p>Se não for indicado outro prazo, a entrega é feita no máximo 30 dias após a encomenda. Verifique o estado da embalagem à receção e reporte qualquer dano ao transportador.</p>'],
        'devolucoes' => ['Devoluções e livre resolução', '<h2>Direito de livre resolução</h2><p>Tem 14 dias, a contar da receção dos bens, para resolver o contrato sem indicar motivo (Decreto-Lei n.º 24/2014). Pode usar o <a href="/livre-resolucao/">formulário de livre resolução</a> ou outra declaração inequívoca.</p><h2>Reembolso</h2><p>Reembolsamos todos os pagamentos no prazo de 14 dias após tomarmos conhecimento da sua decisão, podendo aguardar pela receção dos bens.</p><h2>Devolução dos bens</h2><p>Deve devolver os bens no prazo de 14 dias após a comunicação. Os custos diretos da devolução ficam a seu cargo, salvo indicação em contrário. Responde pela depreciação resultante de manuseamento além do necessário para verificar a natureza e o funcionamento do bem.</p><p>Morada para devolução: [empresa campo="morada"], [empresa campo="cp_localidade"].</p>'],
        'livre-resolucao' => ['Livre resolução', '<p>Use este formulário para comunicar a resolução do contrato dentro do prazo de 14 dias. Receberá uma confirmação por e-mail com a data e hora do pedido.</p>[livre_resolucao]'],
        'garantia' => ['Garantia', '<p>Os bens novos têm garantia legal de 3 anos a contar da entrega (Decreto-Lei n.º 84/2021). Em caso de falta de conformidade, o consumidor pode exigir reparação ou substituição, redução do preço ou resolução do contrato, nos termos da lei.</p><p>Para acionar a garantia, contacte-nos com o número da encomenda e a descrição do problema.</p>' . $id],
        'termos-e-condicoes' => ['Termos e condições', '<h2>1. Identificação do vendedor</h2>' . $id . '<h2>2. Encomendas</h2><p>A encomenda só fica concluída após a confirmação no botão «Encomenda com obrigação de pagar». Os preços incluem IVA à taxa legal em vigor. Os custos de envio são indicados antes da confirmação.</p><h2>3. Pagamento</h2><p>Os meios de pagamento disponíveis são apresentados no checkout.</p><h2>4. Entrega</h2><p>Ver <a href="/entregas/">Entregas</a>.</p><h2>5. Livre resolução e devoluções</h2><p>Ver <a href="/devolucoes/">Devoluções e livre resolução</a>.</p><h2>6. Garantia</h2><p>Ver <a href="/garantia/">Garantia</a>.</p><h2>7. Livro de Reclamações e litígios</h2><p>Ver <a href="/livro-de-reclamacoes/">Livro de Reclamações</a> e <a href="/resolucao-de-litigios/">Resolução de litígios</a>.</p><h2>8. Lei aplicável</h2><p>Aplica-se a lei portuguesa. Os consumidores residentes noutros Estados da UE mantêm a proteção imperativa da sua lei nacional.</p>'],
        'politica-de-privacidade' => ['Política de privacidade', '<h2>Responsável pelo tratamento</h2>' . $id . '<h2>Dados tratados e finalidades</h2><p>Tratamos os dados necessários para processar encomendas (identificação, morada, contactos, dados de faturação), cumprir obrigações legais e responder a pedidos. Só enviamos comunicações comerciais com o seu consentimento.</p><h2>Fundamento e conservação</h2><p>Execução do contrato, obrigação legal e consentimento. Conservamos os dados pelo tempo necessário a cada finalidade e aos prazos legais.</p><h2>Destinatários</h2><p>Transportadoras, prestadores de pagamento e de alojamento, na medida do necessário.</p><h2>Direitos</h2><p>Pode pedir acesso, retificação, apagamento, limitação, portabilidade e opor-se ao tratamento, através de [empresa campo="email"]. Pode reclamar junto da Comissão Nacional de Proteção de Dados (www.cnpd.pt).</p>'],
        'politica-de-cookies' => ['Política de cookies', '<p>Usamos cookies estritamente necessários ao funcionamento da loja (carrinho e sessão). Cookies de análise ou marketing só são usados com o seu consentimento, que pode alterar a qualquer momento em «Configurar cookies», no rodapé.</p><p>Esta loja não carrega, por defeito, nenhum serviço de análise ou publicidade. Se vier a usar algum, deve ser listado aqui com finalidade e prazo.</p>'],
        'livro-de-reclamacoes' => ['Livro de Reclamações', '<p>Pode apresentar uma reclamação no Livro de Reclamações Eletrónico: <a href="https://www.livroreclamacoes.pt" rel="noopener">www.livroreclamacoes.pt</a>.</p>'],
        'resolucao-de-litigios' => ['Resolução de litígios', '<p>Em caso de litígio de consumo, o consumidor pode recorrer a uma entidade de resolução alternativa de litígios. Entidade a que aderimos: [empresa campo="entidade_ral"].</p><p>Informação geral: <a href="https://www.consumidor.gov.pt" rel="noopener">Portal do Consumidor</a>.</p>'],
    ];
}

